LZ.data.grammar.push({id:"g-pps",title:"Present perfect or past simple",rule:["Past simple: finished time (yesterday, in 2019, when I was young, ago).","Present perfect: unfinished time or no time given, life experience, recent news with a present result.","since + point in time; for + period. The present perfect continuous stresses duration (I've been waiting for an hour)."],qs:[{t:"mc",q:"I ___ my keys. Can you help me look for them?",o:["had lost","lost","was losing","have lost"],a:3,x:"Past action with a present result → present perfect."},{t:"mc",q:"We ___ to Rome three years ago.",o:["have been","went","have gone","had gone"],a:1,x:"‘ago’ is finished time → past simple."},{t:"gap",q:"She ___ (work) here since 2019.",a:["has worked","has been working","'s worked","'s been working"],x:"since + point in time → present perfect (simple or continuous)."},{t:"mc",q:"How long ___ each other?",o:["did you know","are you knowing","have you known","do you know"],a:2,x:"State verb (know) + duration up to now → present perfect simple."},{t:"gap",q:"I ___ (not see) Tom since the summer.",a:["haven't seen","have not seen"],x:"Negative present perfect with since."},{t:"mc",q:"This is the first time I ___ sushi.",o:["have eaten","ate","am eating","eat"],a:0,x:"It's the first time + present perfect."},{t:"mc",q:"When ___ your driving test?",o:["do you pass","have you passed","have you been passing","did you pass"],a:3,x:"Questions with ‘When’ ask about a finished time → past simple."},{t:"gap",q:"You look exhausted! What ___ you ___ (do)?",a:["have been doing"],x:"Present perfect continuous explains a present result of a recent activity."}]},{id:"g-narr",title:"Narrative tenses",rule:["Past simple: the main events in order.","Past continuous: background or an action in progress when something happened.","Past perfect: an action before another past action (had + past participle)."],qs:[{t:"mc",q:"I ___ a shower when the phone rang.",o:["was having","had","have had","had had"],a:0,x:"Action in progress interrupted → past continuous."},{t:"mc",q:"When we arrived at the cinema, the film ___.",o:["was already starting","already started","had already started","has already started"],a:2,x:"The film started before we arrived → past perfect."},{t:"gap",q:"She was tired because she ___ (run) for two hours.",a:["had been running"],x:"Past perfect continuous: duration before a past moment."},{t:"mc",q:"It was a beautiful morning. The sun ___ and the birds were singing.",o:["shone","was shining","had shone","has shone"],a:1,x:"Background description → past continuous."},{t:"gap",q:"By the time the police arrived, the thieves ___ (escape).",a:["had escaped"],x:"by the time + past perfect."},{t:"mc",q:"He ___ the door, turned on the light and sat down.",o:["opened","has opened","had opened","was opening"],a:0,x:"A sequence of completed actions → past simple."},{t:"mc",q:"I didn't recognise her because she ___ her hair.",o:["has cut","cut","was cutting","had cut"],a:3,x:"The haircut happened before I saw her → past perfect."},{t:"gap",q:"While I ___ (walk) home, I saw an old friend.",a:["was walking"],x:"while + past continuous."}]},{id:"g-future",title:"Future forms",rule:["will: decisions made now, predictions, promises and offers.","going to: plans already decided; predictions based on evidence.","Present continuous: fixed arrangements. Future continuous: in progress at a future time. Future perfect: completed before a future time."],qs:[{t:"mc",q:"Look at those clouds! It ___ rain.",o:["rains","will","is going to","is raining"],a:2,x:"Prediction based on present evidence → going to."},{t:"mc",q:"‘The phone's ringing.’ ‘I ___ it.’",o:["'m going to get","'ll get","get","'m getting"],a:1,x:"Decision at the moment of speaking → will."},{t:"mc",q:"I ___ my grandparents on Saturday – it's all arranged.",o:["visit","will have visited","will visit","am visiting"],a:3,x:"Fixed arrangement → present continuous."},{t:"gap",q:"This time next week, I ___ (lie) on a beach.",a:["will be lying","'ll be lying"],x:"In progress at a future moment → future continuous."},{t:"gap",q:"By 2030, scientists ___ (find) a cure.",a:["will have found","'ll have found"],x:"Completed before a future time → future perfect."},{t:"mc",q:"The train ___ at 7.45 tomorrow morning.",o:["leaves","will be leaving","is going to leave","will have left"],a:0,x:"Timetables → present simple."},{t:"mc",q:"I'll call you as soon as I ___ home.",o:["will get","get","am going to get","will have got"],a:1,x:"After time conjunctions (as soon as, when, before) use the present, not will."},{t:"mc",q:"Don't worry, I ___ tell anyone your secret.",o:["am not telling","don't","won't","am not going to"],a:2,x:"Promise → will/won't."}]},{id:"g-cond",title:"Conditionals",rule:["Zero: if + present, present (general truths). First: if + present, will (real future).","Second: if + past, would (unreal present/future). Third: if + past perfect, would have + pp (unreal past).","Mixed: if + past perfect, would + infinitive (past cause, present result). unless = if not; provided / as long as = only if."],qs:[{t:"mc",q:"If you heat ice, it ___.",o:["will melt","melts","melted","would melt"],a:1,x:"General truth → zero conditional."},{t:"gap",q:"If I ___ (have) more time, I would learn to play the piano.",a:["had"],x:"Second conditional: if + past simple."},{t:"mc",q:"If she had left earlier, she ___ the train.",o:["wouldn't miss","didn't miss","won't miss","wouldn't have missed"],a:3,x:"Third conditional: would have + past participle."},{t:"mc",q:"___ you study, you won't pass.",o:["Provided","As long as","Unless","If"],a:2,x:"unless = if not."},{t:"gap",q:"If I hadn't stayed up so late, I ___ (not be) so tired now.",a:["wouldn't be","would not be"],x:"Mixed conditional: past cause, present result."},{t:"mc",q:"You can borrow my car ___ you drive carefully.",o:["as long as","in case","otherwise","unless"],a:0,x:"as long as = only if."},{t:"mc",q:"Take an umbrella ___ it rains.",o:["unless","in case","if","provided"],a:1,x:"in case = as a precaution because something might happen."},{t:"gap",q:"If it ___ (not rain) tomorrow, we'll have a picnic.",a:["doesn't rain","does not rain"],x:"First conditional: if + present simple."}]},{id:"g-wish",title:"Wishes and regrets",rule:["wish / if only + past simple: a present situation you want to be different.","wish + past perfect: regret about the past.","wish + would: annoyance about someone's behaviour, or wanting something to change. It's time + past simple."],qs:[{t:"gap",q:"I wish I ___ (can) speak Spanish.",a:["could"],x:"Present ability → wish + could."},{t:"mc",q:"I wish I ___ that – it was a stupid thing to say.",o:["don't say","wouldn't say","didn't say","hadn't said"],a:3,x:"Regret about the past → past perfect."},{t:"mc",q:"I wish you ___ interrupting me!",o:["will stop","stopped","would stop","had stopped"],a:2,x:"Annoyance at someone's behaviour → wish + would."},{t:"gap",q:"If only I ___ (live) closer to the sea.",a:["lived"],x:"Present situation → past simple."},{t:"mc",q:"It's time we ___ home.",o:["went","would go","go","have gone"],a:0,x:"It's time + past simple."},{t:"gap",q:"She wishes she ___ (study) medicine instead of law.",a:["had studied","'d studied"],x:"Past regret → had + past participle."},{t:"mc",q:"I'd rather you ___ my phone without asking.",o:["wouldn't use","don't use","didn't use","not use"],a:2,x:"would rather + subject + past simple."},{t:"mc",q:"I wish it ___ so cold today.",o:["won't be","isn't","hadn't been","wasn't"],a:3,x:"Present situation → past simple (were is also possible)."}]},{id:"g-passive",title:"Passive and causative",rule:["be + past participle in any tense: The bridge was built / is being built / will be built.","Reporting: It is said that… / He is said to be… / He is believed to have left.","Causative: have / get something done – someone else does it for you."],qs:[{t:"gap",q:"The museum ___ (build) in 1890.",a:["was built"],x:"Past simple passive."},{t:"mc",q:"My car ___ at the moment, so I'm taking the bus.",o:["repairs","is being repaired","is repaired","has repaired"],a:1,x:"Present continuous passive: in progress now."},{t:"mc",q:"I'm going to ___ my hair cut tomorrow.",o:["have","make","do","let"],a:0,x:"Causative: have something done."},{t:"gap",q:"The winner ___ (announce) next week.",a:["will be announced","is going to be announced"],x:"Future passive."},{t:"mc",q:"He is said ___ the richest man in the town.",o:["be","to be","being","that he is"],a:1,x:"be said + to-infinitive."},{t:"mc",q:"The thieves are believed ___ the country.",o:["to leave","having left","to have left","leaving"],a:2,x:"Earlier action → perfect infinitive."},{t:"gap",q:"We got our kitchen ___ (paint) last month.",a:["painted"],x:"get something + past participle."},{t:"mc",q:"English ___ in many countries around the world.",o:["speaks","has spoken","is speaking","is spoken"],a:3,x:"General fact, agent unimportant → present simple passive."}]},{id:"g-reported",title:"Reported speech",rule:["Tenses usually move back: am → was, will → would, have done → had done.","Change pronouns and time words: today → that day, tomorrow → the next day.","Reporting verbs: suggest + -ing / that…; advise/warn/remind + object + to; deny/admit + -ing; apologise for + -ing."],qs:[{t:"mc",q:"‘I'm tired,’ she said. → She said she ___ tired.",o:["was","will be","has been","is"],a:0,x:"Present → past."},{t:"gap",q:"‘I'll call you tomorrow.’ → He said he ___ call me the next day.",a:["would"],x:"will → would."},{t:"mc",q:"‘Where do you live?’ → She asked me where ___.",o:["do I live","I live","I lived","did I live"],a:2,x:"Reported questions use statement word order."},{t:"mc",q:"He suggested ___ to the beach.",o:["to go","going","that we going","go"],a:1,x:"suggest + -ing."},{t:"gap",q:"‘Don't forget your passport.’ → She reminded me ___ my passport.",a:["to take","to bring","not to forget"],x:"remind somebody + to-infinitive."},{t:"mc",q:"He denied ___ the window.",o:["break","that break","to break","breaking"],a:3,x:"deny + -ing."},{t:"mc",q:"‘Have you finished?’ → He asked me ___ I had finished.",o:["if","did","that","what"],a:0,x:"Yes/no questions are reported with if/whether."},{t:"gap",q:"‘You should see a doctor.’ → She advised me ___ a doctor.",a:["to see"],x:"advise somebody + to-infinitive."}]},{id:"g-relative",title:"Relative clauses",rule:["who (people), which (things), whose (possession), where (places), when (times).","Defining clauses have no commas and can use that; the pronoun can be left out when it's the object.","Non-defining clauses add extra information between commas: never use that. which can refer to a whole clause."],qs:[{t:"mc",q:"The woman ___ lives next door is a doctor.",o:["whose","which","who","where"],a:2,x:"Person → who."},{t:"gap",q:"That's the man ___ car was stolen.",a:["whose"],x:"Possession → whose."},{t:"mc",q:"My brother, ___ lives in Paris, is visiting us.",o:["whom","that","which","who"],a:3,x:"Non-defining clause about a person → who (not that)."},{t:"mc",q:"She passed all her exams, ___ surprised everyone.",o:["who","which","what","that"],a:1,x:"which refers to the whole previous clause."},{t:"gap",q:"This is the hotel ___ we stayed last year.",a:["where","in which","that","which"],x:"Place → where (or ‘in which’; ‘that/which’ need ‘in’ at the end)."},{t:"mc",q:"The book ___ I borrowed was fascinating.",o:["–","whose","what","who"],a:0,x:"Object relative pronoun in a defining clause can be omitted (or use that/which)."},{t:"mc",q:"I'll never forget the day ___ I met you.",o:["when","where","which","whose"],a:0,x:"Time → when."},{t:"mc",q:"Is there anything ___ I can do to help?",o:["what","that","which","who"],a:1,x:"After anything / everything / nothing use that (or leave the pronoun out), not what."}]},{id:"g-modals",title:"Modals of deduction and obligation",rule:["must (certain it's true), might/may/could (possible), can't (certain it's not true).","Past: must have / might have / can't have + past participle.","must / have to (obligation), don't have to (not necessary), mustn't (not allowed), should have + pp (criticism of a past action), needn't have + pp (did it, but it wasn't necessary)."],qs:[{t:"mc",q:"She ___ be at home – her car's outside.",o:["can't","shouldn't","might not","must"],a:3,x:"Logical certainty → must."},{t:"mc",q:"He ___ be hungry – he's just eaten a huge meal.",o:["mustn't","shouldn't","can't","doesn't have to"],a:2,x:"Certain it's not true → can't."},{t:"gap",q:"I can't find my wallet. I ___ (leave) it in the taxi.",a:["might have left","may have left","could have left","must have left"],x:"Past possibility/deduction → modal + have + past participle."},{t:"mc",q:"You ___ wear a uniform at our school – you can wear what you like.",o:["don't have to","shouldn't","can't","mustn't"],a:0,x:"Not necessary → don't have to."},{t:"mc",q:"You ___ use your phone during the exam. It's forbidden.",o:["don't have to","mustn't","needn't","might not"],a:1,x:"Prohibition → mustn't."},{t:"gap",q:"You ___ (tell) me! I would have helped.",a:["should have told","should've told","ought to have told"],x:"Criticism of a past action → should have + pp."},{t:"mc",q:"I ___ have bought so much food – nobody came.",o:["couldn't","can't","needn't","mustn't"],a:2,x:"needn't have + pp = did it, but it wasn't necessary."},{t:"mc",q:"They ___ have seen us – we were hidden behind the trees.",o:["should","must","needn't","can't"],a:3,x:"Certain it didn't happen → can't have."}]},{id:"g-gerinf",title:"Gerunds and infinitives",rule:["+ -ing: enjoy, avoid, mind, suggest, deny, admit, consider, can't stand, look forward to, be used to, after prepositions.","+ to: want, decide, hope, promise, refuse, manage, afford, seem, would like.","Change of meaning: remember/forget/stop/try/regret + -ing or + to."],qs:[{t:"mc",q:"I'm looking forward to ___ you.",o:["see","have seen","seeing","to see"],a:2,x:"look forward TO (preposition) + -ing."},{t:"gap",q:"She refused ___ (answer) my question.",a:["to answer"],x:"refuse + to-infinitive."},{t:"mc",q:"I stopped ___ a coffee on the way to work.",o:["having","to have","had","have"],a:1,x:"stop + to = stop in order to do something."},{t:"mc",q:"Do you remember ___ this photo? We were so young!",o:["taken","take","to take","taking"],a:3,x:"remember + -ing = a memory of the past."},{t:"gap",q:"Please remember ___ (lock) the door when you leave.",a:["to lock"],x:"remember + to = don't forget to do something."},{t:"mc",q:"We couldn't afford ___ a new car.",o:["to buy","bought","buy","buying"],a:0,x:"afford + to-infinitive."},{t:"gap",q:"I'm not used to ___ (get) up so early.",a:["getting"],x:"be used to + -ing = be accustomed to."},{t:"mc",q:"Have you tried ___ the computer off and on again?",o:["turn","turning","to turn","turned"],a:1,x:"try + -ing = experiment to see if it works."}]},{id:"g-compare",title:"Comparisons, so/such, too/enough",rule:["Comparatives and superlatives: bigger, more interesting, the best. much/far/a lot + comparative.","as + adjective + as; not as/so … as; the more…, the more…","so + adjective; such (a) + adjective + noun; too + adjective; adjective + enough; enough + noun."],qs:[{t:"mc",q:"This test was ___ easier than the last one.",o:["most","more","very","much"],a:3,x:"much + comparative."},{t:"gap",q:"The ___ (hard) you work, the more you'll learn.",a:["harder"],x:"the + comparative…, the + comparative."},{t:"mc",q:"It was ___ a good film that I watched it twice.",o:["enough","too","such","so"],a:2,x:"such + a + adjective + noun."},{t:"mc",q:"He isn't old ___ to drive.",o:["enough","too","so","such"],a:0,x:"adjective + enough."},{t:"gap",q:"My sister isn't as tall ___ me.",a:["as"],x:"not as + adjective + as."},{t:"mc",q:"The coffee was ___ hot to drink.",o:["very","enough","so","too"],a:3,x:"too + adjective + to-infinitive."},{t:"mc",q:"That's the ___ meal I've ever had.",o:["baddest","worst","worse","most bad"],a:1,x:"bad → worse → the worst."},{t:"gap",q:"She speaks English ___ (fluent) than her brother.",a:["more fluently"],x:"Comparative adverb: more + adverb."}]},{id:"g-linking",title:"Linking words: contrast and purpose",rule:["although / even though / while + clause; despite / in spite of + noun or -ing.","However, / Nevertheless, start a new sentence. whereas compares two facts.","Purpose: to / in order to / so as to + infinitive; so that + clause. in case = as a precaution."],qs:[{t:"mc",q:"___ the rain, we enjoyed the trip.",o:["Despite","However","Even though","Although"],a:0,x:"despite + noun."},{t:"mc",q:"___ it was late, he kept working.",o:["However","In spite of","Even though","Despite"],a:2,x:"even though + clause."},{t:"gap",q:"She saved money ___ that she could travel.",a:["so"],x:"so that + clause (purpose)."},{t:"mc",q:"The job was well paid. ___, I didn't enjoy it.",o:["Although","Whereas","Despite","However"],a:3,x:"New sentence + comma → However."},{t:"mc",q:"I left early ___ miss the traffic.",o:["for not","so that","in order not to","so as"],a:2,x:"in order not to + infinitive."},{t:"gap",q:"In spite ___ feeling ill, she went to work.",a:["of"],x:"in spite OF + -ing."},{t:"mc",q:"My brother loves sport, ___ I prefer reading.",o:["whereas","in spite","however","despite"],a:0,x:"whereas compares two contrasting facts in one sentence."},{t:"mc",q:"Take some money ___ you need a taxi.",o:["so that","in case","unless","otherwise"],a:1,x:"in case = because it's possible that."}]}),LZ.data.grammar.push({id:"g-usedto",title:"Used to, would, be used to",rule:["used to + infinitive: past habits and states that are no longer true (I used to live in Prague).","would + infinitive: repeated past actions only – not states (We would play outside every evening).","be / get used to + -ing or noun: be (or become) accustomed to something (I'm used to getting up early)."],qs:[{t:"mc",q:"When I was a child, I ___ afraid of the dark.",o:["used to be","was used to being","would be","got used to be"],a:0,x:"A past state (be afraid) → used to. ‘Would’ is only for repeated actions."},{t:"gap",q:"My grandfather ___ (tell) us stories every Sunday.",a:["would tell","used to tell"],x:"Repeated past action: would or used to."},{t:"mc",q:"I've lived in London for years, so I'm used to ___ in heavy traffic.",o:["drive","drove","driving","have driven"],a:2,x:"be used to + -ing."},{t:"mc",q:"Did you ___ play football at school?",o:["be used to","use to","using to","used to"],a:1,x:"In questions and negatives with ‘did’: use to (no -d)."},{t:"gap",q:"It took me a long time to get used ___ the cold weather.",a:["to"],x:"get used TO + noun."},{t:"mc",q:"She ___ have long hair, but now it's short.",o:["would","is used to","gets used to","used to"],a:3,x:"A past state that has changed → used to (not would)."},{t:"gap",q:"I didn't ___ (like) vegetables, but now I love them.",a:["use to like"],x:"Negative: didn't use to + infinitive."},{t:"mc",q:"You'll soon ___ used to the new timetable.",o:["be","get","have","use"],a:1,x:"get used to = gradually become accustomed."}]},{id:"g-articles",title:"Articles: a, an, the or nothing",rule:["a / an: one of many, first mention, jobs (She's an engineer).","the: something already known or unique, superlatives, rivers, seas, plural country names (the USA).","No article: general plural and uncountable nouns (Cats are clever), most countries, cities, meals, and fixed phrases like go to school / at home / by bus."],qs:[{t:"mc",q:"My brother is ___ architect.",o:["an","–","a","the"],a:0,x:"Jobs take a/an; ‘architect’ starts with a vowel sound → an."},{t:"mc",q:"___ money doesn't always bring happiness.",o:["Some","The","A","–"],a:3,x:"Uncountable noun used in a general sense → no article."},{t:"gap",q:"This is ___ best pizza I've ever eaten.",a:["the"],x:"Superlatives take ‘the’."},{t:"mc",q:"We went to ___ Netherlands last summer.",o:["a","–","the","an"],a:2,x:"Country names with a plural or ‘kingdom/states’ take ‘the’: the Netherlands, the UK."},{t:"mc",q:"I usually go to work by ___ bus.",o:["a","the","one","–"],a:3,x:"Fixed phrase: by bus / by train (no article)."},{t:"gap",q:"I saw a dog and a cat in the garden. ___ dog was chasing the cat.",a:["the"],x:"Second mention → the."},{t:"mc",q:"She plays ___ violin in an orchestra.",o:["an","the","–","a"],a:1,x:"Musical instruments usually take ‘the’: play the violin."},{t:"mc",q:"What ___ amazing view!",o:["a","the","an","–"],a:2,x:"What + a/an + (adjective) + singular noun. ‘amazing’ starts with a vowel sound → an."}]},{id:"g-quant",title:"Quantifiers",rule:["much / little + uncountable nouns; many / few + plural nouns.","a few / a little = some (positive); few / little = not many / not much (negative).","each and every + singular noun; both (two things), either / neither (one of two), all / none (three or more)."],qs:[{t:"mc",q:"There isn't ___ milk left – can you buy some?",o:["much","few","many","a few"],a:0,x:"Uncountable noun in a negative → much."},{t:"mc",q:"Very ___ people came to the meeting, so we cancelled it.",o:["a little","a few","few","little"],a:2,x:"Negative meaning with a plural noun → few."},{t:"gap",q:"I've got a ___ friends in Spain, so I often go there.",a:["few"],x:"a few + plural noun = some (positive)."},{t:"mc",q:"___ of my parents speaks French – they only speak English.",o:["Both","Neither","None","Either"],a:1,x:"Neither = not one and not the other (two people), with a singular verb."},{t:"mc",q:"___ student has to bring a pencil.",o:["Both","All","Most","Every"],a:3,x:"every + singular noun + singular verb."},{t:"gap",q:"We've got very ___ time, so let's hurry.",a:["little"],x:"Negative meaning with an uncountable noun → little."},{t:"mc",q:"I invited ten friends, but ___ of them could come.",o:["none","no","neither","any"],a:0,x:"none of + a group of more than two."},{t:"mc",q:"You can take ___ road – they both go to the station.",o:["either","neither","every","all"],a:0,x:"either = one or the other of two."}]},{id:"g-questions",title:"Indirect questions and question tags",rule:["Indirect questions use statement word order: Could you tell me where the station is? (not where is the station).","Yes/no indirect questions use if or whether: Do you know if the shop is open?","Question tags repeat the auxiliary with the opposite polarity: You're coming, aren't you? She didn't call, did she?"],qs:[{t:"mc",q:"Could you tell me what time ___?",o:["starts the film","the film starts","does the film start","is the film starting at"],a:1,x:"Indirect question: statement word order, no ‘do’."},{t:"gap",q:"Do you know ___ the library is open on Sundays?",a:["if","whether"],x:"Yes/no indirect question → if / whether."},{t:"mc",q:"You haven't seen my keys, ___?",o:["don't you","haven't you","have you","did you"],a:2,x:"Negative sentence → positive tag with the same auxiliary."},{t:"mc",q:"She plays tennis, ___?",o:["does she","didn't she","isn't she","doesn't she"],a:3,x:"Present simple positive → doesn't she?"},{t:"gap",q:"I'm late, ___ I?",a:["aren't"],x:"Special case: I am → aren't I?"},{t:"mc",q:"I wonder where ___.",o:["she went","has she gone to","did she go","went she"],a:0,x:"After ‘I wonder’: statement word order."},{t:"mc",q:"Let's go to the beach, ___?",o:["don't we","will we","do we","shall we"],a:3,x:"Let's … → shall we?"},{t:"gap",q:"Nobody called while I was out, ___ they?",a:["did"],x:"‘Nobody’ is negative, so the tag is positive; ‘nobody’ takes ‘they’ in tags."}]}),LZ.data.grammar.push({id:"g-phrasal",title:"Phrasal verbs",rule:["Many Part 1 and Part 4 answers are phrasal verbs: put off (postpone), turn down (refuse), call off (cancel), look into (investigate).","Separable verbs can take the object in the middle: turn the offer down / turn down the offer – but a pronoun must go in the middle: turn it down.","Some have three parts and never separate: look forward to, get on with, come up with, run out of."],qs:[{t:"mc",q:"The concert was ___ because the singer was ill.",o:["called off","put up","turned out","taken over"],a:0,x:"call off = cancel."},{t:"mc",q:"She ___ a brilliant idea for the school project.",o:["came across","came up with","came down with","came round"],a:1,x:"come up with = think of an idea."},{t:"gap",q:"We've run out ___ milk – can you buy some?",a:["of"],x:"run out of = have none left."},{t:"mc",q:"I was offered the job, but I turned it ___.",o:["off","over","down","away"],a:2,x:"turn down = refuse. The pronoun ‘it’ goes between the verb and the particle."},{t:"mc",q:"The police are ___ the cause of the fire.",o:["looking into","looking after","looking up to","looking out"],a:0,x:"look into = investigate."},{t:"gap",q:"Don't put ___ your homework until the last minute.",a:["off"],x:"put off = postpone."},{t:"mc",q:"It took Maria months to get ___ the flu.",o:["through","over","by","off"],a:1,x:"get over = recover from an illness or a shock."},{t:"mc",q:"I really look forward ___ from you.",o:["to hear","hearing","to hearing","for hearing"],a:2,x:"look forward to + -ing – ‘to’ is a preposition here."}]},{id:"g-deppreps",title:"Dependent prepositions",rule:["Adjectives, verbs and nouns are often followed by a fixed preposition: interested in, good at, afraid of, depend on, succeed in, reason for.","After a preposition, use a noun or -ing: She's keen on climbing.","Part 1 often tests the preposition that follows the gap – read the word after the gap before you choose."],qs:[{t:"gap",q:"Are you interested ___ joining the drama club?",a:["in"],x:"interested in + -ing."},{t:"mc",q:"The price of the trip depends ___ how many people go.",o:["of","from","on","at"],a:2,x:"depend on."},{t:"mc",q:"He was accused ___ stealing the money.",o:["for","of","with","about"],a:1,x:"accuse somebody of something."},{t:"gap",q:"My sister is very good ___ solving puzzles.",a:["at"],x:"good at + -ing."},{t:"mc",q:"She finally succeeded ___ passing her driving test.",o:["to","at","on","in"],a:3,x:"succeed in + -ing."},{t:"mc",q:"What's the reason ___ the delay?",o:["for","of","about","to"],a:0,x:"the reason for something."},{t:"gap",q:"I'm not very keen ___ horror films.",a:["on"],x:"keen on something."},{t:"mc",q:"The museum is famous ___ its collection of old maps.",o:["about","for","by","with"],a:1,x:"famous for something."}]},{id:"g-causative",title:"Have / get something done",rule:["have / get + object + past participle: somebody else does it for you (I had my hair cut).","It can also describe something bad that happens to you: She had her bag stolen.","Keep the tense in ‘have’: I'm having my car repaired / I'll get the windows cleaned."],qs:[{t:"mc",q:"I ___ my eyes tested last week.",o:["had","made","did","let"],a:0,x:"had + object + past participle."},{t:"gap",q:"We're getting our kitchen ___ (paint) next month.",a:["painted"],x:"get + object + past participle."},{t:"mc",q:"Tom had his phone ___ on the bus.",o:["steal","stealing","stolen","to steal"],a:2,x:"Something bad that happened: had his phone stolen."},{t:"mc",q:"Where do you usually ___ your hair cut?",o:["make","have","do","take"],a:1,x:"have your hair cut."},{t:"gap",q:"I need to get my passport ___ (renew) before the trip.",a:["renewed"],x:"get + object + past participle."},{t:"mc",q:"They're ___ a new swimming pool built in their garden.",o:["making","doing","having","letting"],a:2,x:"Present continuous of have: they're having it built."},{t:"mc",q:"You should get that tooth ___ by a dentist.",o:["look at","looked at","looking at","to look at"],a:1,x:"get + object + past participle of the phrasal verb: looked at."},{t:"gap",q:"My grandparents have their shopping ___ (deliver) every Friday.",a:["delivered"],x:"have + object + past participle."}]},{id:"g-sosuch",title:"So, such, too and enough",rule:["so + adjective / adverb (that): It was so cold that we stayed in.","such (a/an) + adjective + noun (that): It was such a cold day that we stayed in.","too + adjective (+ to-infinitive) = more than is good; adjective + enough / enough + noun = the right amount."],qs:[{t:"mc",q:"It was ___ a boring film that I fell asleep.",o:["so","such","too","very"],a:1,x:"such a + adjective + noun."},{t:"mc",q:"The soup was ___ hot to eat.",o:["too","so","such","enough"],a:0,x:"too + adjective + to-infinitive."},{t:"gap",q:"She spoke ___ quickly that I couldn't understand her.",a:["so"],x:"so + adverb + that."},{t:"mc",q:"He isn't ___ to drive a car.",o:["enough old","old enough","too old","so old"],a:1,x:"adjective + enough."},{t:"mc",q:"We don't have ___ to buy tickets for everyone.",o:["money enough","enough money","too money","such money"],a:1,x:"enough + noun."},{t:"gap",q:"They were ___ nice people that we invited them back.",a:["such"],x:"such + adjective + plural noun (no ‘a’)."},{t:"mc",q:"The box was ___ heavy for me to lift.",o:["enough","such","too","so much"],a:2,x:"too + adjective + for somebody + to-infinitive."},{t:"mc",q:"There were ___ many people that we couldn't get in.",o:["such","too","so","enough"],a:2,x:"so many / so much + noun + that."}]}),(function(){const e=(t,o)=>o.forEach(([a,n,i])=>LZ.data.vocab.push({deck:t,term:a,def:n,eg:i}));e("Phrasal verbs",[["put off","delay doing something","We've put off the meeting until Friday."],["come across","find or meet by chance","I came across an old photo of my grandparents."],["turn down","refuse an offer or request","She turned down the job because of the hours."],["run out of","have none left","We've run out of milk."],["look forward to","feel happy about something that will happen","I'm looking forward to the holidays."],["carry on","continue","Carry on reading while I make a call."],["give up","stop doing or trying","He gave up smoking last year."],["take up","start a new hobby or activity","I've taken up yoga."],["set up","start a business or organisation","They set up a small café."],["get over","recover from an illness or bad experience","It took her months to get over the flu."],["break down","stop working (machines); lose control emotionally","Our car broke down on the motorway."],["bring up","raise a child; mention a subject","She was brought up by her aunt."],["call off","cancel","The match was called off because of snow."],["come up with","think of an idea or plan","We need to come up with a better name."],["cut down on","reduce the amount of","I'm trying to cut down on sugar."],["find out","discover information","Can you find out what time the train leaves?"],["get on with","have a good relationship with","I get on well with my colleagues."],["go through","experience something difficult","He went through a hard time after the divorce."],["keep up with","stay at the same level or speed as","It's hard to keep up with the latest technology."],["let down","disappoint","Don't let your team down."],["look up to","admire and respect","She has always looked up to her older brother."],["make up","invent a story; become friends again","He made up an excuse for being late."],["pick up","learn informally; collect","I picked up some Italian while living in Rome."],["point out","tell someone a fact they may not have noticed","She pointed out a mistake in my essay."],["put up with","tolerate","I can't put up with this noise any longer."],["run into","meet by chance","I ran into an old teacher at the station."],["sort out","solve or organise","Let's sort out the problem before the weekend."],["take after","look or behave like an older relative","He really takes after his father."],["turn up","arrive, often unexpectedly","Only five people turned up to the meeting."],["work out","find a solution; exercise","I can't work out how to use this app."]]),e("Collocations",[["make a decision","decide (never ‘do a decision’)","We need to make a decision by Friday."],["make an effort","try hard","Please make an effort to arrive on time."],["make progress","improve","You've made great progress this term."],["make a mistake","do something wrong","Everyone makes mistakes."],["do research","study a subject in detail","Scientists are doing research into the virus."],["do your best","try as hard as you can","Don't worry – just do your best."],["do damage","cause harm","The storm did a lot of damage."],["take a risk","do something that might have bad results","Starting a business means taking a risk."],["take part in","participate","Over 500 runners took part in the race."],["take advantage of","use an opportunity","Take advantage of the sunny weather."],["pay attention","listen or watch carefully","Pay attention to the instructions."],["heavy traffic","a lot of vehicles (not ‘strong traffic’)","We were stuck in heavy traffic."],["strong coffee","coffee with a lot of flavour","I need a strong coffee this morning."],["a high salary","a lot of money for work","The job offers a high salary."],["catch a cold","become ill with a cold","I caught a cold on holiday."],["keep a secret","not tell anyone","Can you keep a secret?"],["break a record","do better than anyone before","She broke the world record."],["save time","use less time","Online shopping saves time."],["waste money","use money badly","Don't waste money on things you don't need."],["raise awareness","make people know about a problem","The campaign raises awareness of plastic pollution."],["reach an agreement","agree after discussion","The two sides finally reached an agreement."],["meet a deadline","finish something on time","We worked all night to meet the deadline."],["bitterly disappointed","extremely disappointed","Fans were bitterly disappointed by the result."],["highly unlikely","very improbable","It's highly unlikely that it will snow."]]),e("Dependent prepositions",[["interested in","adjective + in","She's interested in photography."],["good at","adjective + at","He's really good at maths."],["afraid of","adjective + of","My sister is afraid of spiders."],["responsible for","adjective + for","Who is responsible for this mess?"],["similar to","adjective + to","Your phone is similar to mine."],["keen on","adjective + on","I'm not very keen on horror films."],["aware of","adjective + of","Are you aware of the risks?"],["capable of","adjective + of","She's capable of winning the race."],["depend on","verb + on","It depends on the weather."],["apologise for","verb + for","He apologised for being late."],["accuse someone of","verb + object + of","They accused him of lying."],["succeed in","verb + in + -ing","She succeeded in passing the exam."],["insist on","verb + on + -ing","He insisted on paying for dinner."],["concentrate on","verb + on","I can't concentrate on my work."],["prevent someone from","verb + object + from + -ing","The rain prevented us from playing."],["belong to","verb + to","Does this bag belong to you?"],["complain about","verb + about","They complained about the noise."],["rely on","verb + on","You can always rely on me."],["congratulate someone on","verb + object + on","We congratulated her on her new job."],["protect someone from","verb + object + from","Sunscreen protects your skin from damage."],["reason for","noun + for","What's the reason for the delay?"],["increase in","noun + in","There's been an increase in prices."],["solution to","noun + to","We need a solution to this problem."],["advantage of","noun + of","One advantage of living here is the view."]]),e("Word families",[["SUCCEED","success (n) · successful / unsuccessful (adj) · successfully (adv)","The event was a huge success."],["DECIDE","decision (n) · decisive / indecisive (adj) · decisively (adv)","He's very indecisive."],["EMPLOY","employer / employee / employment / unemployment (n) · unemployed (adj)","Unemployment has fallen."],["APPEAR","appearance / disappearance (n) · disappear (v) · apparent (adj) · apparently (adv)","Apparently, the shop is closing."],["CREATE","creation / creativity / creator (n) · creative (adj) · creatively (adv)","The job needs a lot of creativity."],["BELIEVE","belief (n) · believable / unbelievable (adj) · unbelievably (adv)","The view was unbelievably beautiful."],["COMFORT","comfort (n) · comfortable / uncomfortable (adj) · comfortably (adv)","The seats were really uncomfortable."],["ACHIEVE","achievement (n) · achievable (adj)","Winning the prize was a great achievement."],["DEPEND","dependence / independence (n) · dependent / independent / dependable (adj)","Teenagers want more independence."],["EXPLAIN","explanation (n) · explanatory (adj) · unexplained (adj)","There's no explanation for it."],["HELP","helpful / unhelpful / helpless (adj) · helpfully (adv)","The staff were extremely helpful."],["KNOW","knowledge (n) · knowledgeable (adj) · unknown (adj)","She's very knowledgeable about art."],["LOSE","loss (n) · lost (adj) · loser (n)","The company made a huge loss."],["PERSUADE","persuasion (n) · persuasive (adj)","She wrote a very persuasive essay."],["POSSIBLE","possibility / impossibility (n) · impossible (adj) · possibly (adv)","There's a possibility of rain."],["PREFER","preference (n) · preferable (adj) · preferably (adv)","Call me – preferably before noon."],["RELY","reliability (n) · reliable / unreliable (adj) · reliably (adv)","The bus service is very unreliable."],["SATISFY","satisfaction / dissatisfaction (n) · satisfied / satisfying / satisfactory (adj)","Customer satisfaction is our priority."],["STRONG","strength (n) · strengthen (v) · strongly (adv)","Exercise strengthens your muscles."],["WIDE","width (n) · widen (v) · widely (adv)","The book is widely read."]]),e("Confusing words",[["affect / effect","affect is a verb; effect is usually a noun","The weather affects my mood. It had a big effect."],["borrow / lend","borrow = take for a while; lend = give for a while","Can I borrow your pen? Can you lend me your pen?"],["remind / remember","remind someone; remember something yourself","Remind me to call Mum. I remembered to call."],["rise / raise","rise has no object; raise needs an object","Prices rose. They raised prices."],["actually / currently","actually = in fact; currently = now","I'm currently living in Brno."],["sensible / sensitive","sensible = practical; sensitive = easily upset or aware of feelings","That's a sensible idea. She's very sensitive."],["economic / economical","economic = about the economy; economical = saving money","This car is very economical."],["fun / funny","fun = enjoyable; funny = makes you laugh","The party was fun. The film was funny."],["lose / loose","lose = not find / not win; loose = not tight","Don't lose your keys. These jeans are loose."],["job / work","job is countable; work is uncountable","I've got a new job. I have a lot of work."],["say / tell","tell someone something; say something (to someone)","Tell me the truth. She said hello."],["travel / trip / journey","travel (general activity); trip (going and returning); journey (from A to B)","The journey took six hours."],["advice / advise","advice is a noun (uncountable); advise is a verb","She advised me to wait. Good advice."],["alone / lonely","alone = without others; lonely = sad because you're alone","I live alone but I'm never lonely."],["even / even though","even is an adverb; even though joins clauses","Even though it rained, we went."],["during / for / while","during + noun; for + period; while + clause","I slept during the film / for two hours / while you drove."]]),e("Idioms",[["a piece of cake","very easy","The test was a piece of cake."],["break the ice","make people feel relaxed at first meeting","He told a joke to break the ice."],["hit the books","study hard","I need to hit the books before the exam."],["under the weather","slightly ill","I'm feeling a bit under the weather."],["once in a blue moon","very rarely","We only eat out once in a blue moon."],["cost an arm and a leg","be very expensive","That jacket cost an arm and a leg."],["get the hang of","learn how to do something","I'm getting the hang of this new phone."],["on the tip of my tongue","almost remembered","Her name is on the tip of my tongue."],["the last straw","the final problem that makes you lose patience","When the bus was late again, it was the last straw."],["keep an eye on","watch carefully","Can you keep an eye on my bag?"],["in the long run","eventually, over a long period","It will save you money in the long run."],["make ends meet","have just enough money to live","They struggle to make ends meet."],["see eye to eye","agree","We don't always see eye to eye."],["a blessing in disguise","something that seems bad but turns out well","Missing the flight was a blessing in disguise."],["take something with a pinch of salt","not completely believe it","Take online reviews with a pinch of salt."],["out of the blue","unexpectedly","She called me out of the blue."]])})();
